head.script:
scwin.__hasErrorLog = function() {
    var err = WebSquare.logger.getErrorLog();
    return err ? true : false;
}
scwin.__isSameWidth = function() {
    var width = WebSquare.wUnit.getJq("#checkcombobox1_itemTable_1_checkbox").width() + WebSquare.wUnit.getJq("#checkcombobox1_itemTable_1 label").width();
    var selectbox = WebSquare.wUnit.getJq("#checkcombobox1_main_tbody").width();
    if (selectbox >= width) {
        return true;
    }
    return false;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 샘플파일을 실행 후 ctrl+마우스우클릭으로 로그보기를 선택한다.
    //1. Run the sample file and select ctrl + right-click to view the log.
    // verify step 1. 로그가 정상으로 보여진다.(이전에는 Cannot read property "style" of null 발생)
    //1. The log is displayed as normal.(Formerly Can not read property "style" of null)
    WebSquare.wUnit.addCommand("assert", "scwin.__hasErrorLog()", "false");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 콤보박스를 클릭한다.
    //2. Click the combo box.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('checkcombobox1').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 2. 콤보박스 데이터중 가장 긴 텍스트만큼 콤보박스 넓이로 보여진다.
    //2. The longest text in combo box data is displayed as combo box width.
    WebSquare.wUnit.addCommand("assert", "scwin.__isSameWidth()", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.jsonData = [{
        "label": "a1",
        "value": "a1",
        "a": "a"
    }, {
        "label": "aaaaaaaaa2",
        "value": "a2",
        "a": "a"
    }, {
        "label": "b1",
        "value": "b1",
        "a": "b"
    }, {
        "label": "a3",
        "value": "a3",
        "a": "a"
    }];
    dataList2.setJSON(jsonData);
    //Function unitTest
    //Created By: Sang.do
    //Created By: 13-Feb-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
